'use strict';
const assert=require('node:assert/strict'),{create}=require('../demo-core'),{create:policy}=require('../br03-policy'),F=require('../fixtures'),data=require('../br03-demo-snapshots');let groups=0;
function check(name,fn){fn();groups++;console.log('PASS '+name);}
const fresh=(verified=true)=>{const core=create();core.setScenario('normal');if(verified){core.requestPhone();core.resolvePhone('success');}return {core,p:policy({core,fixture:F,config:data})};};
const u=id=>F.units.find(x=>x.id===id);
check('four configured states use actual unit identity and current amounts',()=>{const {core,p}=fresh();for(const [id,state] of [['SIM_BJ01_U03','N'],['SIM_BJ01_U04','P'],['SIM_BJ02_U03','L'],['SIM_BJ02_U04','PL']]){const f=p.facts(u(id));assert.equal(f.state,state);if(f.promoLabel)assert.equal(f.snapshot.rent_total,core.formalAmounts([id],6).rent_total);}});
check('unverified visitors do not receive term-qualified promo claims',()=>{const {core,p}=fresh(false);assert.equal(p.facts(u('SIM_BJ01_U04')).promoLabel,'');assert.equal(core.authorized(),false);});
check('unconfirmed lease cannot inherit a campaign from a default',()=>{const {core,p}=fresh();core.setRequirement(3.5,null,false);assert.equal(p.facts(u('SIM_BJ01_U04')).promoLabel,'');});
check('changing term removes ineligible promotions without changing demand',()=>{const {core,p}=fresh();core.setTerm(3);assert.equal(p.facts(u('SIM_BJ01_U04')).promoLabel,'');assert.equal(core.state().requirement.capacity_m3,3.5);});
check('changed price revision hides the old catalogue campaign',()=>{const {core}=fresh();const state=core.state();state.prices.SIM_BJ01_U04=999;const next=create({state});assert.equal(policy({core:next,fixture:F,config:data}).facts(u('SIM_BJ01_U04')).promoLabel,'');});
check('inactive and expired campaigns cannot display',()=>{for(const change of [{active:false},{until:'2026-01-01'}]){const {core}=fresh(),config=structuredClone(data);Object.assign(config.campaigns[0],change);assert.equal(policy({core,fixture:F,config}).facts(u('SIM_BJ01_U04')).promoLabel,'');}});
check('marketing tags on the old store fixture cannot create unit promotions',()=>{const {p}=fresh();assert.equal(p.facts(u('SIM_BJ03_U03')).promoLabel,'');});
check('inventory counts come only from a declared complete same-capacity group',()=>{const {p}=fresh();assert.equal(p.facts(u('SIM_BJ02_U03')).inventoryCount,1);assert.equal(p.facts(u('SIM_BJ01_U03')).inventoryCount,null);});
check('incomplete or invalid inventory membership hides scarcity',()=>{const {core}=fresh(),config=structuredClone(data);config.inventoryGroups[0].unitIds.push('missing');assert.equal(policy({core,fixture:F,config}).facts(u('SIM_BJ02_U03')).inventoryLine,'');config.inventoryGroups[0].complete=false;assert.equal(policy({core,fixture:F,config}).facts(u('SIM_BJ02_U03')).inventoryLine,'');});
check('unavailable unit removes promo and purchasing urgency',()=>{const {core,p}=fresh();core.markUnavailable('SIM_BJ02_U04');const f=p.facts(u('SIM_BJ02_U04'));assert.equal(f.state,'UNAVAILABLE');assert.equal(f.promoLabel,'');assert.equal(f.inventoryLine,'');assert.equal(core.state().requirement.term_months,6);});
check('same unit renders identical campaign and price facts across pages',()=>{const {p}=fresh();assert.deepEqual(p.facts(u('SIM_BJ02_U04')),p.facts(u('SIM_BJ02_U04')));});
check('linked capacity uses capacity matching without inventing selected objects',()=>{const {p}=fresh();const d=p.describe(u('SIM_BJ01_U04'),'S01');assert.match(d.lines[0],/^容量匹配/);assert(!d.lines[0].includes('您选择'));});
check('actual item selections use only names from the persisted catalogue IDs',()=>{const {core,p}=fresh();core.setEstimate({source:'items_estimate',estimated_volume:.576,target_volume:.576,term_months:6,term_confirmed:true,items:[{id:'box',variant:'M',quantity:1}]});const d=p.describe(u('SIM_BJ01_U03'),'S02');assert(d.lines[1].includes(data.itemNames.box));assert.match(d.lines[1],/^您选择/);});
check('unmatched but rentable capacities are not marked as matching',()=>{const {p}=fresh();const d=p.describe(u('SIM_BJ01_U01'),'S02');assert.equal(d.matches,false);assert.equal(d.lines[0],'其他可租容量');});
check('browse copy follows the approved volume bands without renaming the unit',()=>{const {core,p}=fresh();core.setRequirement(null,null,false);for(const v of [.75,1,3,6,10,20,50]){assert.equal(p.describe({volume:v},'S01').lines.length,1);assert(p.generic(v,'S02').length>0);}assert.equal(u('SIM_BJ01_U03').name,F.units.find(x=>x.id==='SIM_BJ01_U03').name);});
check('policy emits no invented quota, savings, transport or size-check prompt',()=>{const {p}=fresh();const text=JSON.stringify(F.units.map(x=>[p.facts(x),p.describe(x,'S02')]));assert(!/优惠名额|整期省|免费搬运|核对.*尺寸|正在看|倒计时/.test(text));});
check('all Beijing stores and source units remain intact',()=>{assert.equal(F.stores.filter(x=>x.city==='北京').length,30);assert.equal(F.units.filter(x=>x.store_id.startsWith('SIM_BJ')).length,120);});
console.log(JSON.stringify({groups,result:'PASS'}));
